class Job:
    def __init__(self, r_min, r_max, C_min, C_max, d, p, pred_jobs):
        self.r_min = r_min
        self.r_max = r_max
        self.C_min = C_min
        self.C_max = C_max
        self.d = d
        self.p = p
        self.pred_jobs = pred_jobs
        self.suspensions = {} # {pred_job_id: (sus_min, sus_max)}

class ExecutionScenario:
    def __init__(self, job_set):
        self.job_values = {} # {job_id: {'r_J': val, 'C_J': val, 'sus_J_prime_J': {}}}
        for job_J in job_set:
            r_J = random.uniform(job_J.r_min, job_J.r_max)
            C_J = random.uniform(job_J.C_min, job_J.C_max)
            sus_times = {}
            for pred_J_prime in job_J.pred_jobs:
                sus_min, sus_max = job_J.suspensions[pred_J_prime.id]
                sus_times[pred_J_prime.id] = random.uniform(sus_min, sus_max)
            self.job_values[job_J.id] = {'r_J': r_J, 'C_J': C_J, 'sus_J_prime_J': sus_times}

def get_potentially_ready_jobs(job_set_J, dispatched_jobs_D):
    R = set()
    for job_J in job_set_J:
        if job_J not in dispatched_jobs_D:
            all_predecessors_dispatched = True
            for pred_J_prime in job_J.pred_jobs:
                if pred_J_prime not in dispatched_jobs_D:
                    all_predecessors_dispatched = False
                    break
            if all_predecessors_dispatched:
                R.add(job_J)
    return R

def calculate_rho_min(job_J, node_N):
    # node_N stores f_min_J_prime for dispatched predecessors
    predecessor_earliest_completion_times = []
    for pred_J_prime in job_J.pred_jobs:
        f_min_J_prime = node_N.get_f_min(pred_J_prime)
        sus_min_J_prime_J = job_J.get_sus_min(pred_J_prime)
        predecessor_earliest_completion_times.append(f_min_J_prime + sus_min_J_prime_J)

    if not predecessor_earliest_completion_times:
        rho_min_J = job_J.r_min
    else:
        rho_min_J = max(job_J.r_min, max(predecessor_earliest_completion_times))
    return rho_min_J

def calculate_rho_max(job_J, node_N):
    # node_N stores f_max_J_prime for dispatched predecessors
    predecessor_latest_completion_times = []
    for pred_J_prime in job_J.pred_jobs:
        f_max_J_prime = node_N.get_f_max(pred_J_prime)
        sus_max_J_prime_J = job_J.get_sus_max(pred_J_prime)
        predecessor_latest_completion_times.append(f_max_J_prime + sus_max_J_prime_J)

    if not predecessor_latest_completion_times:
        rho_max_J = job_J.r_max
    else:
        rho_max_J = max(job_J.r_max, max(predecessor_latest_completion_times))
    return rho_max_J

def calculate_rho_hp_J(job_J, R, rho_max_values):
    rho_hp_J = float('inf')
    for J_prime in R:
        if J_prime.p < job_J.p: # J_prime has higher priority
            rho_hp_J = min(rho_hp_J, rho_max_values[J_prime.id])
    return rho_hp_J

def calculate_rho_any_J(R, rho_max_values):
    rho_any_J = float('inf')
    for J_prime in R:
        rho_any_J = min(rho_any_J, rho_max_values[J_prime.id])
    return rho_any_J

def update_certainly_running_jobs(chi_current, new_job_J, pred_J_set, f_min_values, s_max_J):
    chi_next = {new_job_J.id}
    for J_prime_id in chi_current:
        if J_prime_id not in pred_J_set: # J_prime is not a predecessor of new_job_J
            if f_min_values[J_prime_id] > s_max_J:
                chi_next.add(J_prime_id)
    return chi_next

# This is a constraint to apply to A_tilde_min_i
for i in range(1, m + 1):
    A_tilde_min[i] = max(A_tilde_min[i], s_min_J)

def apply_lemma6_constraint(A_tilde_max, chi_current, pred_J_set, s_max_J):
    p = len(chi_current.intersection(pred_J_set))
    for i in range(1, p):
        A_tilde_max[i] = min(A_tilde_max[i], s_max_J)
    return A_tilde_max

def check_merge_criterion_A(node_N1, node_N2, m):
    for i in range(1, m + 1):
        # Check for overlap or contiguity:
        # max(start1, start2) <= min(end1, end2) + 1
        if not (max(node_N1.A_min[i], node_N2.A_min[i]) <= min(node_N1.A_max[i], node_N2.A_max[i]) + 1):
            return False
    return True

def check_merge_criterion_F(node_N1, node_N2):
    # Assuming D_N1 == D_N2 from criterion 1
    # F is stored as a dictionary {job_id: [f_min, f_max]}
    for J_id in node_N1.F.keys(): # Iterate over jobs with unfinished successors
        f_min_J_N1, f_max_J_N1 = node_N1.F[J_id]
        f_min_J_N2, f_max_J_N2 = node_N2.F[J_id] # Must exist if D is same

        # Check for overlap or contiguity
        if not (max(f_min_J_N1, f_min_J_N2) <= min(f_max_J_N1, f_max_J_N2) + 1):
            return False
    return True

def check_schedulability(job_set, sag_graph):
    for job_J in job_set:
        # WCRT_J is typically found by traversing the SAG
        # and taking the max(f_max_J - r_min_J) over all nodes where J is dispatched
        WCRT_J = calculate_WCRT_from_sag(job_J, sag_graph)
        if WCRT_J > job_J.d:
            return False # Not schedulable
    return True # Schedulable
